function basicAttack(target,st){const p=S.player,basic=classDef().basic,damage=st.attack*st.basicDamage*basic.coefficient;p.attackAt=S.time+classDef().stats.attackInterval/st.attackSpeed;p.facing=target.x>=p.x?1:-1;p.attackFlash=DB.render.hitFlash;if(basic.kind==='melee'){p.swing={at:S.time,yaw:Math.atan2(target.x-p.x,target.y-p.y)};damageEnemy(target,damage,{element:weaponElement()});if(st.cleave>0)for(const e of instance().enemies)if(e.id!==target.id&&!e.dead&&dist(e,target)<C.cleaveRadius)damageEnemy(e,damage*st.cleave);}else{spawnProjectile(target,damage,{projectile:basic.projectile,element:weaponElement()});const targets=instance().enemies.filter(e=>!e.dead&&e.id!==target.id&&dist(e,p)<st.range&&lineOfSight(p,e)).sort((a,b)=>dist(a,target)-dist(b,target));for(let i=0;i<Math.floor(st.extraShots);i++)spawnProjectile(targets[i%Math.max(1,targets.length)]||target,damage*C.extraShotDamage,{projectile:basic.projectile});}if(st.manaOnHit>0)p.mp=Math.min(st.mp,p.mp+st.manaOnHit);sound(basic.sound);}
function castSkill(id,target,echo=false){const skill=DB.skills[id];if(!skillAllowed(skill))return;const st=stats(),p=S.player,coefficient=skill.coefficient||0,amount=((st[skill.scale]||0)+(skill.defenseScale||0)*st.defense)*coefficient*st.skillDamage*(echo?C.echoDamageRatio:1),options={element:skill.element||weaponElement(),radius:skill.radius,burn:skill.burn,slow:skill.slow,knockback:skill.knockback,color:skill.color,projectile:skill.projectile,pierce:skill.pierce};if(!echo){if(H.skill)H.skill(skill,target);p.mp-=skill.cost;p.skillCooldowns[id]=S.time+Math.max(C.minimumCooldown,skill.cooldown*st.cooldownRate);p.skillAt=S.time+C.autoSkillGap;if(st.shieldOnSkill)shield(st.shieldOnSkill);if(skill.buff)addBuff(id,skill.buff.stats,skill.buff.duration);if(skill.heal)heal(st.hp*skill.heal);if(skill.shield)shield(st.hp*skill.shield);sound(skill.sound);}if(skill.kind==='projectile')spawnProjectile(target,amount,options);else if(skill.kind==='nova')areaDamage(p.x,p.y,skill.radius,amount,options);else if(skill.kind==='targetArea')areaDamage(target.x,target.y,skill.radius,amount,options);else if(skill.kind==='chain'){const victims=instance().enemies.filter(e=>!e.dead&&dist(e,target)<C.chainRange).sort((a,b)=>dist(a,target)-dist(b,target)).slice(0,(skill.chain||1)+Math.floor(st.chain));let last=p;for(const e of victims){damageEnemy(e,amount,options);effect('chain',last.x,last.y,1,skill.color,{x:e.x,y:e.y});last=e;}}else effect('buff',p.x,p.y,1.3,skill.color);if(!echo&&amount>0&&rng()<st.skillEcho)castSkill(id,target,true);}
function playerCombat(){const p=S.player,st=stats(),target=nearestEnemy(Math.max(C.targetRadius,st.range));S.targetId=target?.id||null;if(!target)return;const distance=dist(p,target);if(p.skillAt<=S.time){for(const id of S.skills){if(!id)continue;const skill=DB.skills[id];if(!skillAllowed(skill)||(p.skillCooldowns[id]||0)>S.time||p.mp<skill.cost)continue;if(skill.conditionHp&&p.hp/st.hp>skill.conditionHp)continue;const range=skill.kind==='self'?C.targetRadius:skill.range;if(distance>range)continue;castSkill(id,target);break;}}if(!target.dead&&p.attackAt<=S.time&&distance<=st.range&&lineOfSight(p,target))basicAttack(target,st);}
function telegraph(enemy){const m=DB.monsters[enemy.template],patterns=m.phases?.[enemy.phase-1]?.patterns||m.patterns,pattern=m.boss?patterns[enemy.patternIndex++%patterns.length]:m;emitPattern(enemy,pattern);enemy.castingUntil=S.time+pattern.windup;enemy.attackAt=enemy.castingUntil+Math.max(C.enemyAttackMinimum,(pattern.cooldown||m.cooldown)/(enemy.phase?C.bossEnrageRate:1));}
const pathGrids=new WeakMap();
function pathTo(actor,target){
 const map=mapDef(),w=map.width,h=map.height,sx=Math.floor(actor.x),sy=Math.floor(actor.y),tx=Math.floor(target.x),ty=Math.floor(target.y);
 if(sx<0||sy<0||sx>=w||sy>=h||tx<0||ty<0||tx>=w||ty>=h)return [];
 let grid=pathGrids.get(map);
 if(!grid){
  const size=w*h,walk=new Uint8Array(size);
  for(let i=0;i<size;i++)walk[i]=occupied(map,i%w+.5,Math.floor(i/w)+.5)?0:1;
  grid={walk,parents:new Int32Array(size),queue:new Int32Array(size)};pathGrids.set(map,grid);
 }
 const start=sy*w+sx,goal=ty*w+tx,{walk,parents,queue}=grid;
 if(start===goal||!walk[goal])return [];
 parents.fill(-1);parents[start]=start;queue[0]=start;let length=1;
 for(let cursor=0;cursor<length&&cursor<C.pathMaxNodes;cursor++){
  const cell=queue[cursor],x=cell%w,y=Math.floor(cell/w);
  if(cell===goal){
   const result=[];for(let i=goal;i!==start;i=parents[i])result.push({x:i%w+.5,y:Math.floor(i/w)+.5});
   return result.reverse();
  }
  for(const [dx,dy]of C.pathNeighborOffsets){
   const nx=x+dx,ny=y+dy,next=ny*w+nx;
   if(nx<0||nx>=w||ny<0||ny>=h||!walk[next]||parents[next]!==-1)continue;
   parents[next]=cell;queue[length++]=next;
  }
 }
 return [];
}
function steerEnemy(enemy,target,speed,dt){let aim=target;if(!lineOfSight(enemy,target)){if(!enemy.path||enemy.pathAt<=S.time||enemy.pathTarget!==Math.floor(target.x)+','+Math.floor(target.y)){enemy.path=pathTo(enemy,target);enemy.pathAt=S.time+C.enemyPathReview;enemy.pathTarget=Math.floor(target.x)+','+Math.floor(target.y);}while(enemy.path?.length&&dist(enemy,enemy.path[0])<C.pathWaypointTolerance)enemy.path.shift();aim=enemy.path?.[0]||target;}else enemy.path=[];const d=dist(enemy,aim)||1;moveActor(enemy,(aim.x-enemy.x)/d*speed*dt,(aim.y-enemy.y)/d*speed*dt);enemy.moving=true;}
function updateEnemies(dt,only=null){const map=mapDef(),p=S.player;for(const e of only?[only]:instance().enemies){const m=DB.monsters[e.template];e.flash=Math.max(0,e.flash-dt);e.moving=false;if(e.dead){if(map.kind==='field'&&!e.eventId&&S.time>=e.respawnAt&&dist(e,p)>C.aggroRange){e.dead=false;e.hp=e.maxHp;e.x=e.homeX;e.y=e.homeY;e.phase=0;e.patternIndex=0;e.addsSpawned=false;e.threat={};e.contributions={};e.lastOwner=null;e.engagedUntil=0;e.castingUntil=0;e.attackAt=S.time+C.enemyAttackStartDelay;}continue;}for(const status of e.statuses)if(status.until>S.time&&status.id!=='slow'&&status.next<=S.time){status.next+=C.statusTick;damageEnemy(e,status.power*C.statusTick,{dot:true,sourceOwner:status.owner,element:DB.online.statusElements[status.id]});}e.statuses=e.statuses.filter(s=>s.until>S.time);if(e.dead)continue;if(m.boss){const phase=m.phases?.[e.phase]||(!m.phases&&!e.addsSpawned?{threshold:C.bossPhaseRatio,adds:m.adds}:null);if(phase&&e.hp/e.maxHp<phase.threshold){e.phase++;e.addsSpawned=true;e.patternIndex=0;for(const [i,id]of phase.adds.entries()){const off=C.bossAddOffsets[i%C.bossAddOffsets.length];instance().enemies.push(growth.scaleAdd(spawnEnemy({monster:id,level:e.level,x:e.x+off[0],y:e.y+off[1]},0)));}sound('boss');}}if(e.castingUntil>S.time)continue;const d=dist(e,p),engaged=e.engagedUntil>S.time;if(e.patrol?.length&&d>C.aggroRange&&!engaged){const point=e.patrol[e.patrolIndex%e.patrol.length],aim={x:point[0],y:point[1]};if(dist(e,aim)<C.pathWaypointTolerance)e.patrolIndex++;steerEnemy(e,aim,e.speed,dt);e.homeX=e.x;e.homeY=e.y;continue;}const home=Math.hypot(e.x-e.homeX,e.y-e.homeY);if(home>C.leashRange||d>C.aggroRange&&!engaged&&home>C.playerRadius){steerEnemy(e,{x:e.homeX,y:e.homeY},e.speed,dt);e.hp=Math.min(e.maxHp,e.hp+e.maxHp*C.returnHeal*dt);e.moving=true;continue;}if(d>C.aggroRange&&!engaged)continue;e.facing=p.x>=e.x?1:-1;const range=m.range;if(d>range){const speed=e.speed*(e.statuses.some(s=>s.id==='slow')?C.slowFactor:1);steerEnemy(e,p,speed,dt);}if(d<=range&&e.attackAt<=S.time&&lineOfSight(e,p))telegraph(e);}}
function pointInHazard(h,p){if(h.kind==='line'){const x=p.x-h.x,y=p.y-h.y,along=x*h.dx+y*h.dy,across=Math.abs(x*h.dy-y*h.dx);return along>=-C.playerRadius&&along<=h.length+C.playerRadius&&across<h.radius+C.playerRadius;}const d=Math.hypot(p.x-h.x,p.y-h.y);if(h.kind==='ring')return d<h.radius+C.playerRadius&&d>Math.max(0,h.innerRadius-C.playerRadius);if(h.kind==='cone'){const angle=Math.atan2(p.y-h.y,p.x-h.x)-Math.atan2(h.dy,h.dx),delta=Math.atan2(Math.sin(angle),Math.cos(angle));return d<h.radius+C.playerRadius&&(d<C.playerRadius||Math.abs(delta)<h.angle/2);}return d<h.radius+C.playerRadius;}
function updateHazards(){for(const h of S.hazards){const source=instance().enemies.find(e=>e.id===h.source);if(h.source&&(!source||source.dead)){h.expires=S.time;continue;}if(!h.hit&&h.at<=S.time){h.hit=true;if(pointInHazard(h,S.player))hurtPlayer(h.damage,source,h.element);if(source&&h.kind==='line'&&h.dash)moveActor(source,h.dx*h.length*C.hazardDashFraction,h.dy*h.length*C.hazardDashFraction);}}S.hazards=S.hazards.filter(h=>h.expires>S.time);}
function updateProjectiles(dt){for(const shot of S.projectiles){shot.life-=dt;shot.x+=shot.vx*dt;shot.y+=shot.vy*dt;if(occupied(mapDef(),shot.x,shot.y,0)){shot.life=0;continue;}for(const e of instance().enemies){if(e.dead||shot.hitIds.includes(e.id)||Math.hypot(e.x-shot.x,e.y-shot.y)>shot.radius+C.playerRadius*DB.monsters[e.template].size)continue;shot.hitIds.push(e.id);if(shot.options.radius)areaDamage(shot.x,shot.y,shot.options.radius,shot.damage,shot.options);else damageEnemy(e,shot.damage,shot.options);shot.pierce--;if(shot.pierce<=0||shot.hitIds.length>=C.maxProjectileHits){shot.life=0;break;}}}S.projectiles=S.projectiles.filter(s=>s.life>0);}
// Integrate the same ease-out curve between two times, independent of frame or packet rate.
function dashProgress(remaining){
 const t=1-clamp(remaining/C.dashDuration,0,1);
 return t*(2-t);
}
function advanceMovement(p,input,st,dt,previousTime){
 const len=Math.hypot(input.x,input.y),dx=len>C.inputDeadzone?input.x/Math.max(1,len):0,dy=len>C.inputDeadzone?input.y/Math.max(1,len):0;
 const remaining=p.dashUntil-previousTime,dashTime=clamp(remaining,0,dt),walkTime=dt-dashTime;
 p.moving=!!(dx||dy||dashTime);
 if(dx||dy){p.lastMoveX=dx;p.lastMoveY=dy;}
 if(dashTime){
  const distance=C.dashDistance*(dashProgress(remaining-dashTime)-dashProgress(remaining));
  moveActor(p,p.dashX*distance,p.dashY*distance);
  if(p.dashX)p.facing=p.dashX>0?1:-1;
 }else if(dx)p.facing=dx>0?1:-1;
 if(walkTime>0)moveActor(p,dx*st.speed*walkTime,dy*st.speed*walkTime);
}
function predictMovement(p,input,dt,previousTime){refreshDash(p,previousTime+dt);advanceMovement(p,input,stats(),dt,previousTime);}
function tick(dt,shared=false){if(!S)return;dt=Math.min(dt,C.step);const previousTime=S.time;S.time+=dt;refreshDash();S.playTime+=dt;S.buffs=S.buffs.filter(b=>b.until>S.time);S.notices=S.notices.filter(n=>n.until>S.time);S.lootFeed=S.lootFeed.filter(n=>n.until>S.time);const p=S.player,st=stats();advanceMovement(p,S.input,st,dt,previousTime);p.hp=Math.min(st.hp,p.hp+(st.hpRegen+(mapDef().kind==='town'?st.hp*C.safeRegen:0))*dt);p.mp=Math.min(st.mp,p.mp+st.manaRegen*dt*(mapDef().kind==='town'?1+C.safeRegen:1));p.shield=Math.min(p.shield,st.hp*C.shieldCapRatio);p.flash=Math.max(0,p.flash-dt);p.attackFlash=Math.max(0,(p.attackFlash||0)-dt);if(mapDef().kind!=='town'){if(!shared){updateMechanics();updateTrial();updateEnemies(dt);}playerCombat();updateProjectiles(dt);if(!shared)updateHazards();updateCompanion();}if(!shared)updateWorld();for(const list of [S.effects,S.floats,S.orbs])for(const e of list)e.life-=dt;S.effects=S.effects.filter(x=>x.life>0);S.floats=S.floats.filter(x=>x.life>0);for(const orb of S.orbs)if(S.time-orb.at>C.orbDelay){const d=dist(orb,p)||1;orb.x+=(p.x-orb.x)/d*C.dropMagnetSpeed*dt;orb.y+=(p.y-orb.y)/d*C.dropMagnetSpeed*dt;if(d<C.pickupRadius)orb.life=0;}S.orbs=S.orbs.filter(x=>x.life>0);S.shake=Math.max(0,S.shake-DB.render.shakeDecay*dt);growth.tick(dt);}
function setInput(x,y){if(S)S.input={x:clamp(x,-1,1),y:clamp(y,-1,1)};}
function objectiveProgress(quest,index){const o=quest.objectives[index],record=S.quests[quest.id];let value=0;const key=o.kind==='kill'?(o.group?'killGroup:'+o.group+':'+o.target:'kill:'+o.map+':'+o.target):o.kind+':'+o.target;if(o.kind==='kill')value=record?.baselineMetrics?(S.metrics[key]||0)-(record.baselineMetrics[key]||0):(S.killCounts[o.target]||0)-(record?.baseline?.[o.target]||0);if(o.kind==='boss')value=S.bossKills[o.target]||0;if(['event','tier','trial','mechanism'].includes(o.kind))value=(S.metrics[key]||0)-(quest.repeatable?(record?.baselineMetrics?.[key]||0):0);if(o.kind==='interact')value=S.interactions[o.target]||0;if(o.kind==='material')value=S.materials[o.target]||0;if(o.kind==='visit')value=S.visited[o.target]?1:0;if(o.kind==='discover')value=S.discoveries[o.target]?1:0;return clamp(value,0,o.count);}
function questStatus(id){const q=find(DB.quests,id),r=S.quests[id];if(!q)return 'locked';if(r?.status==='complete'&&!q.repeatable)return 'complete';if(r?.status==='active')return q.objectives.every((o,i)=>objectiveProgress(q,i)>=o.count)?'ready':'active';if(q.repeatable&&r?.completedAt!=null&&S.time-r.completedAt<(q.cooldown||C.questRepeatCooldown))return 'cooling';if((!q.requires||S.quests[q.requires]?.status==='complete')&&S.level>=(q.minLevel||1))return 'available';return 'locked';}
function nearNpc(id){return activeNpcs().some(n=>n.id===id&&dist(n,S.player)<=C.interactRadius);}
function acceptQuest(id){const q=find(DB.quests,id);if(!q||questStatus(id)!=='available')return fail('locked');if(!nearNpc(q.npc))return fail('returnNpc');S.quests[id]={status:'active',baseline:copy(S.killCounts),baselineMetrics:copy(S.metrics),completions:S.quests[id]?.completions||0};notice('questAccepted',{},'good');return ok();}
function grant(reward){if(reward.xp)gainXp(reward.xp);if(reward.gold)S.gold=clamp(S.gold+reward.gold,0,C.maxGold);if(reward.potions)S.potions+=reward.potions;if(reward.points)S.points+=reward.points;for(const [id,n]of Object.entries(reward.materials||{}))addMaterial(id,n);for(const [id,n]of Object.entries(reward.reputation||{}))S.reputation[id]=clamp((S.reputation[id]||0)+n,0,C.repMax);for(const [id,n]of Object.entries(reward.supplies||{})){const c=find(DB.consumables,id);if(c?.pool)S[c.pool]=(S[c.pool]||0)+n;else S.supplies[id]=(S.supplies[id]||0)+n;}if(reward.companion){S.companions[reward.companion]={unlocked:true,bond:S.companions[reward.companion]?.bond||0};if(!S.companionId)S.companionId=reward.companion;}}
function completeQuest(id,choiceId=null){const q=find(DB.quests,id);if(!q||questStatus(id)!=='ready')return fail('locked');if(!nearNpc(q.npc))return fail('returnNpc');const choice=q.choices&&find(q.choices,choiceId);if(q.choices&&!choice)return fail('choiceRequired');for(const o of q.objectives)if(o.consume&&o.kind==='material')S.materials[o.target]-=o.count;const record=S.quests[id];record.status='complete';record.completedAt=S.time;record.completions=(record.completions||0)+1;if(choice){record.choice=choice.id;S.choices[id]=choice.id;}grant(q.rewards);if(choice)grant(choice.rewards);if(q.final)S.chapterDone=true;growth.action('quest');notice('questCompleted',{},'good');sound('level');return ok('',{final:!!q.final});}
function trackedQuest(){const active=DB.quests.find(q=>q.main&&['ready','active'].includes(questStatus(q.id)))||DB.quests.find(q=>['ready','active'].includes(questStatus(q.id)));if(active){const status=questStatus(active.id),index=active.objectives.findIndex((o,i)=>objectiveProgress(active,i)<o.count),objective=active.objectives[Math.max(0,index)],npc=Object.values(DB.maps).flatMap(m=>m.npcs.map(n=>({...n,map:m.id}))).find(n=>n.id===active.npc);return {quest:active,status,line:status==='ready'?text('readyToClaim'):objective.label+' '+objectiveProgress(active,Math.max(0,index))+'/'+objective.count,map:status==='ready'?npc?.map:objective.map||npc?.map,npc:status==='ready'?active.npc:null};}const offer=DB.quests.find(q=>q.main&&questStatus(q.id)==='available');if(offer){const map=Object.values(DB.maps).find(m=>m.npcs.some(n=>n.id===offer.npc));return {quest:offer,status:'available',line:text('questAvailable'),map:map?.id,npc:offer.npc};}return null;}
function guardiansRemaining(){return instance().enemies.filter(e=>e.guardian&&!e.dead).length;}
function nearby(){const map=mapDef(),list=[];for(const n of activeNpcs())list.push({...n,kind:'npc',label:n.name});for(const p of map.portals)list.push({...p,kind:'portal',label:p.name});for(const ch of map.chests)if(!instance().chests[ch.id])list.push({...ch,kind:'chest',label:text('chest')});for(const r of map.resources)if(!instance().resources[r.id]||r.respawn&&S.time-instance().resources[r.id]>=r.respawn)list.push({...r,kind:'resource',label:find(DB.materials,r.type).name});for(const d of map.discoveries)if(!S.discoveries[d.id])list.push({...d,kind:'discovery',label:d.name});for(const m of map.mechanisms)if(!instance().mechanisms[m.id])list.push({...m,kind:'mechanism',label:m.name});for(const e of map.events)list.push({...e,kind:'event',label:e.name});return list.filter(v=>dist(v,S.player)<=C.interactRadius).sort((a,b)=>dist(a,S.player)-dist(b,S.player))[0]||null;}
function adjustRealmStats(values,duel,guildLevel){
 const O=DB.online;
 if(duel){
  Object.assign(values,O.pvpStats[S.classId]);
  values.damageReduction=Math.min(values.damageReduction,O.pvpDamageReductionCap);
  values.lifesteal=Math.min(values.lifesteal,O.pvpLifestealCap);
  values.hpRegen=0;
  values.manaRegen=O.pvpManaRegen;
  for(const key of ['basicDamage','skillDamage','attackSpeed'])values[key]=Math.min(values[key],O.pvpModifierMax);
  values.crit=Math.min(values.crit,O.pvpCritCap);
 }else if(guildLevel){
  const bonus=Math.min(O.guildAuraCap,guildLevel*O.guildAuraPerLevel);
  for(const key of ['hp','attack','spell'])values[key]*=1+bonus;
 }
 return values;
}
function portalAllowed(portal){if(portal.requiresRiftClear&&!S.growth.rift.run?.complete)return fail('riftLocked');if(portal.requiresQuest&&S.quests[portal.requiresQuest]?.status!=='complete')return fail('requiresQuest',{quest:find(DB.quests,portal.requiresQuest).name});if(portal.requiresGuardians&&guardiansRemaining()>0)return fail('requiresGuardians');return ok();}
function interact(){const n=nearby();if(!n)return fail('noInteraction');if(n.kind==='mechanism')return useMechanism(n.id);if(n.kind==='npc'){S.interactions[n.id]=(S.interactions[n.id]||0)+1;return ok('',{interaction:n});}if(n.kind==='discovery'||n.kind==='event')return ok('',{interaction:n});if(n.kind==='portal'){const allowed=portalAllowed(n);if(!allowed.ok)return allowed;const rift=growth.portal(n);if(rift)return rift;if(DB.maps[n.to].kind==='dungeon'&&mapDef().group!==DB.maps[n.to].group)return ok('',{interaction:{...n,kind:'dungeon'}});return enterMap(n.to,n.spawn,S.runTier);}if(n.kind==='chest'){instance().chests[n.id]=true;grant(n);if(rng()<(n.equipmentChance??C.defaultChestEquipmentChance))giveItem(rollEquipment(mapDef().level+(find(DB.dungeonTiers,S.runTier)?.levelBonus||0),n.rarity));return ok();}if(n.kind==='resource'){instance().resources[n.id]=S.time||C.step;addMaterial(n.type,n.amount);growth.gathered(n.type,n.amount);float(n.x,n.y,'+'+n.amount+' '+find(DB.materials,n.type).name,DB.theme.colors.good);sound('loot');return ok();}return ok();}
function enterDungeon(portal,tierId,ruleId=DB.expeditionRules[0].id){const actual=mapDef().portals.find(p=>p.id===portal.id&&p.to===portal.to),tier=find(DB.dungeonTiers,tierId);if(!actual||dist(actual,S.player)>C.interactRadius||!tier)return fail('locked');const allowed=portalAllowed(actual);if(!allowed.ok)return allowed;const map=DB.maps[actual.to];if((S.clears[map.group]||0)<tier.requiredClears)return fail('tierLocked',{count:tier.requiredClears});if(!find(DB.expeditionRules,ruleId))return fail('locked');S.expeditionRule=ruleId;return enterMap(actual.to,actual.spawn,tierId);}
function travel(id){const map=DB.maps[id];if(!map||!map.waypoint||!S.visited[id])return fail('locked');const allowed=canTravel();if(!allowed.ok)return allowed;return enterMap(id,map.waypoint);}
function potion(){return useConsumable(C.healingConsumable);}
function equip(id){if(inCombat())return fail('busy');const item=S.inventory.find(i=>i.id===id),def=item&&find(DB.items,item.template);if(!item||def.classes&&!def.classes.includes(S.classId))return fail('locked');if(id===S.growth.weapon.reserveId)return growth.api.swapWeapon();S.equipment[def.slot]=id;const st=stats();S.player.hp=Math.min(S.player.hp,st.hp);S.player.mp=Math.min(S.player.mp,st.mp);sound('click');return ok(text('equippedNotice'));}
function unequip(slot){if(inCombat())return fail('busy');if(!DB.slots.some(s=>s.id===slot))return fail('locked');S.equipment[slot]=null;const st=stats();S.player.hp=Math.min(S.player.hp,st.hp);S.player.mp=Math.min(S.player.mp,st.mp);return ok();}
function previewItem(item){const def=find(DB.items,item.template),eq={...S.equipment,[def.slot]:item.id};return stats(eq,{[item.id]:item});}
function canDispose(item){if(item&&growth.isReserve(item.id))return false;return !!item&&!item.favorite&&!Object.values(S.equipment).includes(item.id);}
function salvageItem(item,internal=false){if(!canDispose(item))return fail('deleteProtected');S.inventory=S.inventory.filter(i=>i.id!==item.id);addMaterial('ore',find(DB.rarities,item.rarity).salvage);growth.salvage(item);if(!internal)sound('loot');return ok(text('salvaged'));}
function dispose(id,mode='salvage'){if(mapDef().kind!=='town')return fail('townOnly');const item=S.inventory.find(i=>i.id===id);if(!canDispose(item))return fail('deleteProtected');if(mode==='sell'){S.gold=Math.min(C.maxGold,S.gold+Math.round(C.sellValue*find(DB.rarities,item.rarity).multiplier*item.level));S.inventory=S.inventory.filter(i=>i.id!==id);return ok(text('sold'));}return salvageItem(item);}
function favorite(id){const item=S.inventory.find(i=>i.id===id);if(!item)return fail('locked');item.favorite=!item.favorite;return ok();}
function upgradeCost(item){return {gold:Math.ceil(C.upgradeGoldBase*Math.pow(C.upgradeGoldGrowth,item.enhance)),ore:C.upgradeOreBase+Math.floor(item.enhance/C.upgradeOreStep)};}
function upgrade(id){if(mapDef().kind!=='town'||!activeNpcs().some(n=>n.service==='smith'&&dist(n,S.player)<=C.interactRadius))return fail('townOnly');const item=S.inventory.find(i=>i.id===id);if(item&&find(DB.items,item.template).slot==='weapon')return growth.api.forgeMain();if(!item||item.enhance>=C.upgradeMax)return fail('maxUpgrade');const cost=upgradeCost(item);if(S.gold<cost.gold||S.materials.ore<cost.ore)return fail('notEnough');S.gold-=cost.gold;S.materials.ore-=cost.ore;item.enhance++;sound('heavy');return ok(text('upgraded'));}
function craft(id){if(!activeNpcs().some(n=>n.service==='smith'&&dist(n,S.player)<=C.interactRadius))return fail('townOnly');const recipe=find(DB.recipes,id);if(recipe&&S.level<(recipe.minLevel||1))return fail('craftLevelGate',{level:recipe.minLevel});if(recipe&&!reputationAllowed(recipe.reputation))return fail('reputationGate');if(!recipe||recipe.classes&&!recipe.classes.includes(S.classId)||S.gold<recipe.gold||Object.entries(recipe.materials).some(([k,v])=>S.materials[k]<v))return fail('notEnough');S.gold-=recipe.gold;for(const [k,v]of Object.entries(recipe.materials))S.materials[k]-=v;giveItem(makeItem(recipe.smartWeapon?classDef().starter:recipe.item,recipe.rarity,S.level));growth.action('craft');return ok(text('crafted'));}
function buy(id){const npc=activeNpcs().find(n=>n.service==='merchant'&&dist(n,S.player)<=C.interactRadius);if(!npc)return fail('noInteraction');const item=shopInventory(npc).find(i=>i.id===id);if(!item)return fail('locked');const stock=shopStatus(item,npc);if(stock.locked)return fail('shopLevelGate',{level:item.minLevel});if(stock.remaining===0)return fail('soldOut');if(S.gold<item.price)return fail('notEnough');S.gold-=item.price;if(item.kind==='equipment')giveItem(makeItem(item.item,item.rarity,item.level));else if(item.kind==='material')addMaterial(item.material,item.amount);else{const def=find(DB.consumables,item.consumable);if(def.pool)S[def.pool]=(S[def.pool]||0)+item.amount;else S.supplies[def.id]=(S.supplies[def.id]||0)+item.amount;}S.shopPurchases[stock.key]=(S.shopPurchases[stock.key]||0)+1;sound('loot');return ok();}
function rest(meal=false){if(!activeNpcs().some(n=>n.service==='inn'&&dist(n,S.player)<=C.interactRadius))return fail('townOnly');const cost=meal?DB.inn.cost:DB.inn.restCost;if(S.gold<cost)return fail('notEnough');S.gold-=cost;if(meal){addBuff(C.foodBuffId,DB.inn.stats,DB.inn.duration);sound('buff');return ok(text('mealApplied'));}S.player.hp=stats().hp;S.player.mp=stats().mp;sound('heal');return ok(text('healed'));}
function bless(id){if(!activeNpcs().some(n=>n.service==='temple'&&dist(n,S.player)<=C.interactRadius))return fail('townOnly');const blessing=find(DB.blessings,id);if(!blessing)return fail('locked');const current=blessingInfo();if(current?.id===id&&current.remaining>=blessing.duration-C.blessingRefreshTolerance)return fail('blessingFull');if(S.gold<blessing.cost)return fail('notEnough');S.gold-=blessing.cost;S.buffs=S.buffs.filter(b=>!DB.blessings.some(x=>x.id===b.id));addBuff(id,blessing.stats,blessing.duration);sound('buff');return ok();}
function branchPoints(id){return Object.entries(S.talents).reduce((sum,[key,rank])=>sum+(talentIndex[key]?.branch===id?rank:0),0);}
function learn(id){const node=find(DB.talents,id);if(!node||node.class!==S.classId)return fail('locked');if(!selectedBranches().includes(node.branch))return fail('advancementRequired');if(S.level<(node.minLevel||1))return fail('talentLevel',{level:node.minLevel});if((S.talents[id]||0)>=node.maxRank)return fail('learned');if(S.points<node.cost)return fail('noPoints');if(branchPoints(node.branch)<node.requires)return fail('requiresBranch',{count:node.requires});S.points-=node.cost;S.talents[id]=(S.talents[id]||0)+1;sound('buff');return ok(text('talentNotice'));}
function respec(){if(mapDef().kind!=='town')return fail('townOnly');if(S.gold<C.advancementRespecCost)return fail('notEnough');S.gold-=C.advancementRespecCost;for(const node of DB.talents)S.points+=(S.talents[node.id]||0)*node.cost;S.talents={};S.advancements={};S.skills=S.skills.map(id=>skillAllowed(DB.skills[id])?id:null);const st=stats();S.player.hp=Math.min(S.player.hp,st.hp);S.player.mp=Math.min(S.player.mp,st.mp);return ok();}
function equipSkill(slot,id){const skill=DB.skills[id];if(!Number.isInteger(slot)||slot<0||slot>=C.skillSlots||!classDef().skills.includes(id)||!skillAllowed(skill))return fail('lockedSkill');const prior=S.skills.indexOf(id);if(prior>=0)S.skills[prior]=null;S.skills[slot]=id;return ok();}
function snapshot(options={}){if(!S)return null;const source={...S,player:{...S.player,swing:null},input:{x:0,y:0}};for(const k of ['hazards','projectiles','floats','effects','orbs','sounds','notices','lootFeed'])source[k]=[];if(options.currentMapOnly)source.instances={[S.mapId]:S.instances[S.mapId]};return copy(source);}
function load(value){try{const v=copy(value);if(v.version!==C.saveVersion||!find(DB.races,v.raceId)||!find(DB.classes,v.classId)||!DB.maps[v.mapId]||!Number.isInteger(v.level)||v.level<1||v.level>C.maxLevel||!Number.isFinite(v.time)||v.time<0||!Number.isFinite(v.xp)||v.xp<0||!Number.isInteger(v.points)||v.points<0||!Number.isFinite(v.gold)||v.gold<0||!Number.isInteger(v.potions)||v.potions<0||!v.player||!['x','y','hp','mp'].every(k=>Number.isFinite(v.player[k]))||v.player.hp<=0||v.player.mp<0||!Array.isArray(v.inventory)||!v.equipment||!v.talents||!v.quests||!v.instances||!v.instances[v.mapId]||!Array.isArray(v.buffs)||!v.materials)return fail('invalidSave');const ids=new Set();for(const item of v.inventory){if(!item.id||ids.has(item.id)||!find(DB.items,item.template)||!find(DB.rarities,item.rarity)||!Number.isInteger(item.enhance)||item.enhance<0||item.enhance>C.upgradeMax||!Number.isInteger(item.level)||item.level<1||item.level>C.maxMonsterLevel||!Array.isArray(item.affixes)||item.affixes.some(id=>!find(DB.affixes,id))||item.rune&&!find(DB.runes,item.rune))return fail('invalidSave');ids.add(item.id);}for(const slot of DB.slots){const id=v.equipment[slot.id],item=v.inventory.find(i=>i.id===id);if(id&&(!item||find(DB.items,item.template).slot!==slot.id||find(DB.items,item.template).classes&&!find(DB.items,item.template).classes.includes(v.classId)))return fail('invalidSave');}if(Object.entries(v.talents).some(([id,n])=>{const t=find(DB.talents,id);return !t||t.class!==v.classId||!Number.isInteger(n)||n<0||n>t.maxRank;})||!Array.isArray(v.skills)||v.skills.length!==C.skillSlots||v.skills.some(id=>id&&(!find(DB.classes,v.classId).skills.includes(id)||DB.skills[id].unlock>v.level))||new Set(v.skills.filter(Boolean)).size!==v.skills.filter(Boolean).length)return fail('invalidSave');for(const m of DB.materials){v.materials[m.id]??=0;}for(const m of DB.materials)if(!Number.isFinite(v.materials[m.id])||v.materials[m.id]<0)return fail('invalidSave');for(const [id,inst]of Object.entries(v.instances)){inst.events??={};if(!DB.maps[id]||!Array.isArray(inst.enemies)||!inst.chests||!inst.resources)return fail('invalidSave');for(const e of inst.enemies)if(!DB.monsters[e.template]||!['x','y','hp','maxHp','level'].every(k=>Number.isFinite(e[k]))||!Array.isArray(e.statuses))return fail('invalidSave');}if(!v.killCounts||!v.bossKills||!v.interactions||!v.visited||!v.clears)return fail('invalidSave');v.manaPotions??=0;v.supplies??={};v.discoveries??={};v.seenDiscoveries??={};v.shopPurchases??={};v.player.dashCharges??=C.dashCharges;v.player.dashReadyAt??=0;v.player.dashUntil=0;v.player.dashX=0;v.player.dashY=0;v.player.lastMoveX??=v.player.facing||1;v.player.lastMoveY??=0;v.player.consumableReady??={};v.player.consumableReady[C.healingConsumable]??=v.player.potionAt||0;if(!Number.isInteger(v.player.dashCharges)||v.player.dashCharges<0||v.player.dashCharges>C.dashCharges||!Number.isFinite(v.player.dashReadyAt)||!Number.isInteger(v.manaPotions)||v.manaPotions<0||Object.values(v.supplies).some(n=>!Number.isInteger(n)||n<0))return fail('invalidSave');const previous=S;S=v;try{networkStats=null;progressDefaults(true);if(!Number.isInteger(S.masteryLevel)||S.masteryLevel<0||!Number.isFinite(S.masteryXp)||S.masteryXp<0||!Number.isInteger(S.masteryPoints)||S.masteryPoints<0||Object.entries(S.masteryRanks).some(([id,n])=>!find(DB.masteryTracks,id)||!Number.isInteger(n)||n<0))throw Error('mastery');for(const inst of Object.values(S.instances))for(const e of inst.enemies){const m=DB.monsters[e.template];e.attack=m.attack*(1+(e.level-1)*C.enemyDamageGrowth)*(e.growthDamageScale||1);e.patrol??=[];e.patrolIndex??=0;}if(Object.values(S.advancements).some(id=>!DB.branches[id]||DB.branches[id].class!==S.classId)||Object.entries(S.advancements).some(([stage,id])=>DB.branches[id].stage!==Number(stage)||Number(stage)>1&&DB.branches[id].parent!==S.advancements[Number(stage)-1])||Object.entries(S.talents).some(([id,n])=>n&&!selectedBranches().includes(find(DB.talents,id).branch))||Object.values(S.reputation).some(n=>!Number.isFinite(n)||n<0)||S.companionId&&!DB.companions.some(c=>c.id===S.companionId)||S.trial&&!DB.trials.some(t=>t.id===S.trial.id))throw Error('progress');fieldSpawns();refreshDash();const p=validPosition(mapDef(),v.player.x,v.player.y);S.player.x=p.x;S.player.y=p.y;S.player.hp=Math.min(S.player.hp,stats().hp);S.player.mp=Math.min(S.player.mp,stats().mp);S.input={x:0,y:0};S.hazards=[];S.projectiles=[];S.effects=[];S.floats=[];S.orbs=[];S.sounds=[];S.notices=[];S.lootFeed=[];S.player.invulnerableUntil=S.time+C.hurtInvulnerability;for(const e of instance().enemies)e.castingUntil=0;return ok();}catch(error){S=previous;return fail('invalidSave');}}catch{return fail('invalidSave');}}
function validate(){const errors=[];for(const ch of DB.classes){if(!ch.sprite||!find(DB.items,ch.starter)||ch.skills.some(id=>!DB.skills[id]))errors.push('Invalid class '+ch.id);}for(const map of Object.values(DB.maps)){if(map.tiles.length!==map.height||map.tiles.some(row=>row.length!==map.width||[...row].some(c=>!DB.terrain[c])))errors.push('Invalid tiles '+map.id);for(const p of map.portals)if(!DB.maps[p.to]||p.requiresQuest&&!find(DB.quests,p.requiresQuest))errors.push('Invalid portal '+p.id);for(const e of map.spawns)if(!DB.monsters[e.monster])errors.push('Invalid spawn '+map.id);}for(const node of DB.talents)if(!DB.branches[node.branch]||node.stats.some(s=>!(s.stat in DB.baseStats)))errors.push('Invalid talent '+node.id);return errors;}
function previewCharacter(raceId,classId){const ch=find(DB.classes,classId),race=find(DB.races,raceId);if(!ch||!race)return null;return apply({...DB.baseStats,...ch.stats},race.stats);}
function routeTo(target){if(!DB.maps[target]||S.mapId===target)return [];const queue=[{id:S.mapId,path:[]}],seen=new Set([S.mapId]);while(queue.length){const node=queue.shift();for(const portal of DB.maps[node.id].portals){if(seen.has(portal.to))continue;const next=[...node.path,{from:node.id,...portal}];if(portal.to===target)return next;seen.add(portal.to);queue.push({id:portal.to,path:next});}}return [];}
function navigationTarget(){const growthTarget=growth.navigation();if(growthTarget)return growthTarget;const track=trackedQuest();if(!track)return null;if(track.map&&track.map!==S.mapId){const route=routeTo(track.map);return route[0]?{x:route[0].x,y:route[0].y,label:route[0].name}:null;}if(track.npc){const npc=mapDef().npcs.find(n=>n.id===track.npc);return npc?{...npc,label:npc.name}:null;}const index=track.quest.objectives.findIndex((o,i)=>objectiveProgress(track.quest,i)<o.count),o=track.quest.objectives[index];if(!o)return null;if(o.kind==='kill'||o.kind==='boss'){const list=instance().enemies.filter(e=>!e.dead&&e.template===o.target).sort((a,b)=>dist(a,S.player)-dist(b,S.player));return list[0]?{x:list[0].x,y:list[0].y,label:DB.monsters[o.target].name}:null;}if(['event','mechanism'].includes(o.kind)){const entries=o.kind==='event'?mapDef().events:mapDef().mechanisms;const point=entries.find(v=>v.id===o.target);return point?{...point,label:point.name}:null;}if(o.kind==='tier'){const boss=instance().enemies.find(e=>DB.monsters[e.template].boss&&!e.dead);return boss?{x:boss.x,y:boss.y,label:DB.monsters[boss.template].name}:null;}if(o.kind==='interact'){const npc=mapDef().npcs.find(n=>n.id===o.target);return npc?{...npc,label:npc.name}:null;}if(o.kind==='discover'){const poi=mapDef().discoveries.find(v=>v.id===o.target);return poi?{...poi,label:poi.name}:null;}if(o.kind==='material'){const resource=mapDef().resources.find(r=>r.type===o.target&&!instance().resources[r.id]);return resource?{...resource,label:find(DB.materials,o.target).name}:null;}return null;}
const growth=window.RPGGrowth({DB,state:()=>S,copy,fail,ok,clamp,dist,apply,stats,classDef,weaponElement,instance,mapDef,inCombat,activeNpcs,notice,effect,sound,float,addMaterial,gainXp,grant,spawnEnemy,enterMap,rng,damageEnemy,text,itemName,upgradeCost,progress:(kind,n)=>H.progress?H.progress(kind,n):false,certify:materials=>H.certify?.(materials)});
window.RPG={DB,adjustRealmStats,dashProgress,previewForge:()=>stats(S.equipment,{},S.growth.weapon.rank+1),predictDash,predictMovement,clearState:()=>{S=null;networkStats=null;},setHooks,acceptNetworkState,clearNetworkState,skillAllowed,weaponElement,elementFactor,masteryNeeded,learnMastery,engrave,receiveSupport,applyResolvedDamage,stepSharedHazards,awardKill,grant,heal,shield,addBuff,fieldSpawns,spawnEnemy,createInstance,updateMechanics,updateWorld,updateTrial,stepEnemy:(e,dt)=>updateEnemies(dt,e),advance,advancementOptions,selectedBranches,reputationStatus,reputationAllowed,companionInfo,selectCompanion,claimCodex,useMechanism,wardCount,startTrial,claimTrial,expedition,emitPattern,worldPhase,activeNpcs,canTravel,blessingInfo,dash,dashInfo,consumableCount,useConsumable,shopInventory,shopStatus,discover,eventStatus,startEvent,claimEvent,pathTo,navigationTarget,previewCharacter,routeTo,create,state:()=>S,stats,itemStats,itemName,itemScore,makeItem,giveItem,xpNeeded,gainXp,mapDef,instance,occupied,moveActor,lineOfSight,enterMap,inCombat,nearby,interact,enterDungeon,portalAllowed,travel,potion,equip,unequip,previewItem,favorite,dispose,upgradeCost,upgrade,craft,buy,rest,bless,branchPoints,learn,respec,equipSkill,questStatus,objectiveProgress,acceptQuest,completeQuest,trackedQuest,guardiansRemaining,tick,setInput,snapshot,load,validate,damageEnemy,castSkill,pointInHazard,text};Object.assign(window.RPG,growth.api);
